 ap=argparse.ArgumentParser();ap.add_argument("--check",action="store_true");args=ap.parse_args();v=load(MODULE,"f1assessmodule");value=assess(v);evidence=value.pop("_evidence");payload=v.BASE_YAML_BYTES(value)
